std::vector<std::pair<size_t, size_t>> collisions;

// Create octree container
XYZ::OctreeBoxC octree;

// Insert all boxes into the octree
for (size_t i = 0; i < boxes.size(); ++i) {
    octree.Insert(i, boxes[i]);
}

// For each box, query for collisions
for (size_t i = 0; i < boxes.size(); ++i) {
    auto candidates = octree.QueryIntersections(boxes[i]);
    for (size_t j : candidates) {
        if (j > i) {  // Avoid duplicates and self-collision
            collisions.emplace_back(i, j);
        }
    }
}

return collisions;

